import {analyze} from "/ask-query.js";
const $=s=>document.querySelector(s),make=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};let context={},busy=false,controller=null;
const photo={'오세훈':'oh','전재수':'jeon','추미애':'chumi','박찬대':'park','추경호':'choo'};
function chip(text,box){const b=make('button',text);b.type='button';b.onclick=()=>ask(text);box.append(b)}
['단체장 직무평가 상위 5명','서울과 부산 비교해줘','주민생활 만족도 하위 3곳'].forEach(t=>chip(t,$('#examples')));
function render(result,q){const a=make('article',undefined,'answer');$('#conversation').append(a);a.append(make('div','tvU 데이터 분석','eyebrow'));if(!result.supported){a.append(make('p',result.message));const c=make('div',undefined,'chips');result.suggestions?.forEach(t=>chip(t,c));a.append(c);return}
 context=result.context;a.append(make('h2',result.title),make('div',result.period+' · '+result.scope,'badge'),make('p',result.summary,'summary'));
 const chart=make('div',undefined,'chart');chart.setAttribute('aria-label',result.title+' 막대그래프');
 result.rows.forEach(r=>{const row=make('div',undefined,'row');row.append(make('span',(r.tied?'공동 ':'')+r.rank+'위','rank'));let av;if(photo[r.name]){av=make('img');av.src='/assets/'+photo[r.name]+'.jpg';av.alt=r.name;av.className='avatar';av.onerror=()=>av.replaceWith(make('span',r.name.slice(0,1),'avatar'))}else av=make('span',(r.name||r.region).slice(0,r.name?1:2),'avatar');row.append(av);const info=make('div');info.append(make('div',r.name||r.region,'name'));if(r.name)info.append(make('div',r.region,'sub'));const track=make('div',undefined,'track'),bar=make('div',undefined,'bar');bar.style.setProperty('--w',r.value/result.max*100+'%');track.append(bar);if(result.metric==='relative')track.append(make('span',undefined,'ref'));info.append(track);row.append(info);const v=make('div',r.value.toFixed(1),'value');v.append(make('small',result.unit));row.append(v);chart.append(row)});a.append(chart,make('p','막대 범위: 0~'+result.max+result.unit+(result.metric==='relative'?' · 점선: 100점':''),'note'));
 const details=make('details'),sum=make('summary','수치표 보기');details.append(sum);const wrap=make('div',undefined,'tablewrap'),table=make('table'),head=make('tr');['순위','지역','이름','수치'].forEach(t=>head.append(make('th',t)));table.append(head);result.rows.forEach(r=>{const tr=make('tr');[(r.tied?'공동 ':'')+r.rank,r.region,r.name||'—',r.value.toFixed(1)+result.unit].forEach(t=>tr.append(make('td',t)));table.append(tr)});wrap.append(table);details.append(wrap);a.append(details);
 result.notes.forEach(n=>a.append(make('p',n,'note')));const source=make('details');source.append(make('summary','출처 · 조사 개요'));source.append(make('p','리얼미터 / 조사 2026.7.28.~7.31. / 전국 18세 이상 8,000명(시도별 500명) / 유·무선 RDD 자동응답 / 지역별 95% 신뢰수준 ±4.4%p / 응답률 3.1% / 2026년 6월 말 주민등록 인구 기준 성·연령·권역 가중. 상대지수에 ±4.4점을 적용하지 않습니다.'));const link=make('a','자료와 전체 순위 보기 ↗');link.href='/realmeter-2026-07.html';link.target='_blank';link.rel='noopener';source.append(link);a.append(source);
 const tools=make('div',undefined,'tools');const csv=make('button','표 내려받기 CSV');csv.onclick=()=>{const content='\ufeff'+[['기준월','지표','순위','지역','이름','수치','단위'],...result.rows.map(r=>['2026-07',result.title,r.rank,r.region,r.name,r.value,result.unit])].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'})),l=make('a');l.href=u;l.download='tvu-2026-07-'+result.metric+'.csv';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};const pdf=make('button','인쇄 / PDF 저장');pdf.onclick=()=>window.print();const replay=make('button','그래프 다시 재생');replay.onclick=()=>chart.querySelectorAll('.bar').forEach(b=>{b.style.animation='none';void b.offsetWidth;b.style.animation=''});tools.append(csv,pdf,replay);a.append(tools);const follow=make('div',undefined,'chips');result.suggestions.forEach(t=>chip(t,follow));a.append(make('p','이어서 질문해보세요','note'),follow)
}
async function ask(q){if(busy)return;busy=true;$('#send').disabled=true;$('#cancel').hidden=false;controller=new AbortController();const u=make('div',undefined,'user');u.append(make('span',q));$('#conversation').append(u);$('#question').value='';$('#status').textContent='등록된 자료를 조회하고 비교 수치를 계산하고 있습니다…';try{const r=await fetch('/api/realmeter',{signal:controller.signal});if(!r.ok)throw Error('자료 조회에 실패했습니다. 잠시 후 다시 시도해 주세요.');const data=await r.json();render(analyze(data,q,context),q);$('#status').textContent='';u.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}catch(e){$('#status').textContent=e.name==='AbortError'?'질문을 중지했습니다.':e.message}finally{busy=false;$('#send').disabled=false;$('#cancel').hidden=true;controller=null}}
$('#form').onsubmit=e=>{e.preventDefault();const q=$('#question').value.trim();if(q)ask(q)};$('#question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#form').requestSubmit()}};$('#cancel').onclick=()=>controller?.abort();$('#reset').onclick=()=>{controller?.abort();context={};$('#conversation').replaceChildren();$('#status').textContent='';$('#question').focus()};const initial=new URLSearchParams(location.search).get('q');if(initial)ask(initial.slice(0,500));
